 const next={...d};for(const [k,v] of Object.entries(d)){const el=$(`[name="${k}"]`,f);if(!el)continue;if(typeof v==='boolean')next[k]=el.checked;else if(typeof v==='number')next[k]=k==='price'?Math.round(Number(el.value)*100):Number(el.value);else if(Array.isArray(v))next[k]=el.value.split(',').map(s=>s.trim()).filter(Boolean);else next[k]=['startsAt','endsAt'].includes(k)&&el.value?await utc(el.value):el.value;}
