 if(kind==='workout')next.exercises=$$('.nested-row',f).map(row=>({exerciseId:Number($('[name=exerciseId]',row).value),sets:Number($('[name=sets]',row).value),reps:$('[name=reps]',row).value,restSeconds:Number($('[name=restSeconds]',row).value)}));
 await api(`/api/admin/records/${kind}${r?'/'+r.id:''}`,{method:r?'PUT':'POST',body:{name:fd.get('name'),data:next,enabled:fd.has('enabled'),sort_order:r?.sort_order??recordsData.length}});await syncConfig();toast('Record saved.');
