function gallery(r){let items=structuredClone(r.media),newFiles=[],coverId=items.find(m=>m.cover)?.id||items[0]?.id,dragged;const dialog=modal(r.name+' · images',`<div class="gallery-manager"><div class="gallery-upload"><b>Make this space yours.</b><p class="hint">Choose multiple photos. Preview before uploading.</p><input id="gallery-files" type="file" accept="image/jpeg,image/png,image/webp,image/heic" ${r.kind==='payment_method'?'':'multiple'}></div><div id="upload-preview" class="thumb-list"></div><button class="btn primary" id="upload-gallery" disabled>${icon('upload')} Upload selected images</button><p class="hint">Drag images or use the arrows to reorder. Choose a cover, add captions, or remove individual images.</p><div id="gallery-thumbs" class="thumb-list"></div><button id="save-gallery" class="btn primary">Save order & cover</button></div>`);
 const renderThumbs=()=>{$('#gallery-thumbs').innerHTML=items.map((m,i)=>`<div class="thumb-tile" draggable="true" data-tile="${m.id}"><img src="${asset(m.thumbnail)}" alt="${E(m.alt||r.name)}">${m.id===coverId?'<span class="badge good">Cover</span>':'<span class="badge">'+(i+1)+'</span>'}<div class="thumb-actions"><button class="icon-btn" data-gallery="left:${m.id}" aria-label="Move image left" ${i===0?'disabled':''}>←</button><button class="icon-btn" data-gallery="right:${m.id}" aria-label="Move image right" ${i===items.length-1?'disabled':''}>→</button><button class="icon-btn" data-gallery="cover:${m.id}" aria-label="Select cover">${icon('star',14)}</button><button class="icon-btn" data-gallery="caption:${m.id}" aria-label="Caption and alt text">${icon('message',14)}</button>${r.kind==='payment_method'?'':`<button class="icon-btn" data-gallery="delete:${m.id}" aria-label="Delete image">${icon('close',14)}</button>`}</div><p class="caption">${E(m.caption||'No caption')}</p></div>`).join('');$$('[data-gallery]').forEach(b=>b.onclick=errorBoundary(async()=>{const [a,id]=b.dataset.gallery.split(':'),i=items.findIndex(m=>m.id===Number(id));if(a==='cover')coverId=Number(id);if(a==='left'&&i>0)[items[i-1],items[i]]=[items[i],items[i-1]];if(a==='right'&&i<items.length-1)[items[i+1],items[i]]=[items[i],items[i+1]];if(a==='delete'){if(!confirm('Remove this image from '+r.name+'? The image file will be deleted.'))return;await api('/api/admin/media/'+id,{method:'DELETE'});items.splice(i,1);if(coverId===Number(id))coverId=items[0]?.id;}if(a==='caption'){const m=items[i],tile=b.closest('.thumb-tile');tile.insertAdjacentHTML('beforeend',`<div class="form" style="padding:10px">${field('Caption','caption',m.caption)}${field('Alt text','alt',m.alt)}<button class="btn secondary small caption-save">Save text</button></div>`);$('.caption-save',tile).onclick=errorBoundary(async()=>{m.caption=$('[name=caption]',tile).value;m.alt=$('[name=alt]',tile).value;await api('/api/admin/media/'+id,{method:'PUT',body:{caption:m.caption,alt:m.alt}});renderThumbs();});return;}renderThumbs();}));$$('[data-tile]').forEach(tile=>{tile.ondragstart=e=>{dragged=Number(tile.dataset.tile);e.dataTransfer.setData('text/plain',String(dragged));tile.classList.add('dragging');};tile.ondragover=e=>e.preventDefault();tile.ondrop=e=>{e.preventDefault();const i=items.findIndex(m=>m.id===dragged),j=items.findIndex(m=>m.id===Number(tile.dataset.tile));if(i>=0&&j>=0)items.splice(j,0,items.splice(i,1)[0]);renderThumbs();};tile.ondragend=()=>tile.classList.remove('dragging');});};renderThumbs();let previewUrls=[];$('#gallery-files').onchange=e=>{previewUrls.forEach(URL.revokeObjectURL);newFiles=[...e.target.files];if(r.kind==='payment_method')newFiles=newFiles.slice(0,1);previewUrls=newFiles.map(URL.createObjectURL);$('#upload-preview').innerHTML=previewUrls.map((url,i)=>`<div class="thumb-tile"><img src="${url}" alt="Upload preview"><p class="caption">${E(newFiles[i].name)}</p></div>`).join('');$('#upload-gallery').disabled=!newFiles.length;};$('#upload-gallery').onclick=errorBoundary(async()=>{const b=$('#upload-gallery');b.disabled=true;try{const fd=new FormData();newFiles.forEach(f=>fd.append('files',f));const uploaded=await api(`/api/admin/media/${r.kind}/${r.id}`,{method:'POST',body:fd,signal:AbortSignal.timeout(90000)});if(r.kind==='payment_method'){items=uploaded;coverId=items[0]?.id;}else{items.push(...uploaded);coverId=coverId||items[0]?.id;}newFiles=[];$('#upload-preview').innerHTML='';renderThumbs();toast('Photos optimized and uploaded.');}finally{b.disabled=!newFiles.length;}});$('#save-gallery').onclick=errorBoundary(async()=>{await api(`/api/admin/media/${r.kind}/${r.id}/order`,{method:'PUT',body:{ids:items.map(m=>m.id),coverId}});dialog.close();await syncConfig();await refresh();toast('Gallery updated.');});dialog.addEventListener('close',()=>previewUrls.forEach(URL.revokeObjectURL),{once:true});}
